mapper.select:
SELECT ar.tenant_id AS tenantId, p.position AS position, ir.input_text AS inputText, ir.parsed_intent AS parsedIntentJson, ir.priority AS priority, ar.status AS status, ar.approval_type AS approvalType, ar.risk_level AS riskLevel, ar.ai_recommendation AS aiRecommendation, ar.submitted_payload AS submittedPayload, ar.modified_payload AS modifiedPayload, ar.decision_reason AS decisionReason, ar.submitted_at AS submittedAt, ar.decided_at AS decidedAt FROM approval_record ar LEFT JOIN intent_request ir ON ir.id = ar.intent_id LEFT JOIN person p ON p.user_id = ir.user_id AND p.tenant_id = ir.tenant_id WHERE ar.id = #{id}
AND ar.tenant_id = #{tenantId}
LIMIT 1

SELECT ar.id AS approvalId, ir.id AS intentId, ir.tenant_id AS tenantId, ir.user_id AS userId, ir.input_text AS inputText, ir.priority AS priority, ir.status AS intentStatus, ir.trace_id AS traceId, ir.create_time AS intentSubmittedAt, ar.approval_type AS approvalType, ar.risk_level AS riskLevel, ar.status AS approvalStatus, ar.decision_reason AS decisionReason, ar.submitted_at AS approvalSubmittedAt, ar.decided_at AS decidedAt, ar.expire_at AS expireAt FROM intent_request ir LEFT JOIN approval_record ar ON ar.id = ( SELECT latest_ar.id FROM approval_record latest_ar WHERE latest_ar.intent_id = ir.id ORDER BY latest_ar.submitted_at DESC, latest_ar.id DESC LIMIT 1 )
ir.tenant_id = #{tenantId} AND ir.user_id = #{userId}
AND ar.status = #{query.status}
AND ar.approval_type = #{query.approvalType}
AND ar.risk_level = #{query.riskLevel}
AND ir.trace_id = #{query.traceId}
AND ir.create_time >= #{query.startTime}
AND ir.create_time <= #{query.endTime}
ORDER BY ir.create_time DESC
